#include <stdexcept>
#include <utility>
#include <vector>

template <class T>
class Ring
{
public:
    void push_back(T value) {}
    void push_front(T value) {}
    T pop_back() { return T{}; }
    T pop_front() { return T{}; }
    T& front() { return dummy_; }
    T& back() { return dummy_; }
    T& operator[](std::size_t i) { return dummy_; }
    std::size_t size() const { return size_; }
    std::size_t capacity() const { return slots_.size(); }

private:
    std::vector<T> slots_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
    T dummy_{};                 // only so the starter compiles: remove it
};

solution.solution.cpp:
#include <stdexcept>
#include <utility>
#include <vector>

template <class T>
class Ring
{
public:
    void push_back(T value)
    {
        if (size_ == slots_.size()) grow();
        slots_[slot(size_)] = std::move(value);
        ++size_;
    }

    void push_front(T value)
    {
        if (size_ == slots_.size()) grow();
        head_ = (head_ + slots_.size() - 1) % slots_.size();
        slots_[head_] = std::move(value);
        ++size_;
    }

    T pop_back()
    {
        check();
        T value = std::move(slots_[slot(size_ - 1)]);
        --size_;
        return value;
    }

    T pop_front()
    {
        check();
        T value = std::move(slots_[head_]);
        head_ = (head_ + 1) % slots_.size();
        --size_;
        return value;
    }

    T& front() { check(); return slots_[head_]; }
    T& back() { check(); return slots_[slot(size_ - 1)]; }
    T& operator[](std::size_t i) { return slots_[slot(i)]; }
    std::size_t size() const { return size_; }
    std::size_t capacity() const { return slots_.size(); }

private:
    std::size_t slot(std::size_t i) const { return (head_ + i) % slots_.size(); }

    void check() const
    {
        if (size_ == 0) throw std::out_of_range("the ring is empty");
    }

    void grow()
    {
        std::vector<T> bigger(slots_.empty() ? 4 : slots_.size() * 2);
        for (std::size_t i = 0; i < size_; ++i) bigger[i] = std::move(slots_[slot(i)]);
        slots_ = std::move(bigger);
        head_ = 0;
    }

    std::vector<T> slots_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

unitTests:
#include <deque>
#include <string>

TEST("a queue") {
    Ring<int> r;
    for (int i = 1; i <= 3; ++i) r.push_back(i);
    CHECK_EQ(r.pop_front(), 1);
    CHECK_EQ(r.pop_front(), 2);
    CHECK_EQ(r.size(), std::size_t{ 1 });
    CHECK_EQ(r.capacity(), std::size_t{ 4 });
}
TEST("a stack") {
    Ring<std::string> r;
    r.push_back("a"); r.push_back("b"); r.push_back("c");
    CHECK_EQ(r.pop_back(), std::string("c"));
    CHECK_EQ(r.back(), std::string("b"));
    CHECK_EQ(r.front(), std::string("a"));
}
TEST("pushing at the front wraps around") {
    Ring<int> r;
    r.push_back(2);
    r.push_front(1);
    r.push_front(0);
    CHECK_EQ(r[0], 0); CHECK_EQ(r[1], 1); CHECK_EQ(r[2], 2);
    CHECK_EQ(r.capacity(), std::size_t{ 4 });
    r.push_back(3);
    r.push_back(4);                  // full: grows while wrapped
    CHECK_EQ(r.capacity(), std::size_t{ 8 });
    for (int i = 0; i < 5; ++i) CHECK_EQ(r[i], i);
}
TEST("empty") {
    Ring<int> r;
    CHECK_THROWS(r.pop_front());
    CHECK_THROWS(r.pop_back());
    CHECK_THROWS(r.front());
    r.push_front(5);
    CHECK_EQ(r.pop_back(), 5);
    CHECK_THROWS(r.back());
}
TEST("matches std::deque on a long random run") {
    Ring<int> r;
    std::deque<int> d;
    unsigned seed = 12345;
    for (int step = 0; step < 20000; ++step)
    {
        seed = seed * 1103515245 + 12345;
        int op = (seed >> 16) % 4;
        if (op == 0) { r.push_back(step); d.push_back(step); }
        else if (op == 1) { r.push_front(step); d.push_front(step); }
        else if (op == 2 && !d.empty()) { CHECK_EQ(r.pop_front(), d.front()); d.pop_front(); }
        else if (op == 3 && !d.empty()) { CHECK_EQ(r.pop_back(), d.back()); d.pop_back(); }
    }
    CHECK_EQ(r.size(), d.size());
    bool same = true;
    for (std::size_t i = 0; i < d.size(); ++i) same = same && r[i] == d[i];
    CHECK(same);
}

